    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        transitions = {
            Iphy3.fct: {
                Iphy3.proxy_pc: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                Iphy3.aashell: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
            },
            Iphy3.proxy_pc: {
                Iphy3.fct: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
            },
            Iphy3.aashell: {
                Iphy3.fct: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_without_proxy_pc(self):
        """
        Prepare transitions to change states without proxy_pc state.

        :return: transitions without proxy_pc state.
        """
        transitions = {
            Iphy3.fct: {
                Iphy3.unix_local: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                Iphy3.aashell: {
                    "action": [
                        "_execute_command_to_change_state"
                    ]
                },
            },
            Iphy3.unix_local: {
                Iphy3.fct: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            Iphy3.aashell: {
                Iphy3.fct: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        state_prompts = {
            Iphy3.fct:
                self._configurations[Iphy3.connection_hops][Iphy3.aashell][Iphy3.fct][
                    "command_params"]["expected_prompt"],
            Iphy3.aashell:
                self._configurations[Iphy3.connection_hops][Iphy3.fct][Iphy3.aashell][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        state_prompts = {
            Iphy3.fct:
                self._configurations[Iphy3.connection_hops][Iphy3.unix_local][Iphy3.fct][
                    "command_params"]["expected_prompt"],
            Iphy3.aashell:
                self._configurations[Iphy3.connection_hops][Iphy3.fct][Iphy3.aashell][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine with proxy_pc state.

        :return: non direct transitions for each state with proxy_pc state.
        """
        state_hops = {
            Iphy3.not_connected: {
                Iphy3.fct: Iphy3.unix_local,
                Iphy3.aashell: Iphy3.unix_local,
            },
            Iphy3.unix_local: {
                Iphy3.fct: Iphy3.proxy_pc,
                Iphy3.aashell: Iphy3.proxy_pc,
            },
            Iphy3.proxy_pc: {
                Iphy3.aashell: Iphy3.fct,
            },
            Iphy3.fct: {
                Iphy3.not_connected: Iphy3.proxy_pc,
                Iphy3.unix_local: Iphy3.proxy_pc,
                Iphy3.unix_local_root: Iphy3.proxy_pc
            },
            Iphy3.aashell: {
                Iphy3.unix_local: Iphy3.fct,
                Iphy3.proxy_pc: Iphy3.fct,
                Iphy3.not_connected: Iphy3.fct,
                Iphy3.unix_local_root: Iphy3.fct
            },
            Iphy3.unix_local_root: {
                Iphy3.fct: Iphy3.unix_local,
                Iphy3.aashell: Iphy3.unix_local,
            }
        }
        return state_hops

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_without_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine without proxy_pc state.

        :return: non direct transitions for each state without proxy_pc state.
        """
        state_hops = {
            Iphy3.not_connected: {
                Iphy3.fct: Iphy3.unix_local,
                Iphy3.aashell: Iphy3.unix_local,
            },
            Iphy3.unix_local: {
                Iphy3.aashell: Iphy3.fct,
            },
            Iphy3.fct: {
                Iphy3.not_connected: Iphy3.unix_local,
                Iphy3.unix_local_root: Iphy3.unix_local
            },
            Iphy3.aashell: {
                Iphy3.unix_local: Iphy3.fct,
                Iphy3.not_connected: Iphy3.fct,
                Iphy3.unix_local_root: Iphy3.fct
            },
            Iphy3.unix_local_root: {
                Iphy3.fct: Iphy3.unix_local,
                Iphy3.aashell: Iphy3.unix_local,
                Iphy3.not_connected: Iphy3.unix_local,
            }
        }
        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(Iphy3, self)._get_packages_for_state(state, observer)

        if not available:
            if state == Iphy3.fct:
                available = {Iphy3.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.shared.enblinux',
                                          'ta_moler.cmd.shared.fct', 'ta_moler.cmd.iphy.fct'],
                             Iphy3.events: ['moler.events.shared', 'moler.events.unix',
                                            'ta_moler.events.iphy']}
            elif state == Iphy3.aashell:
                available = {Iphy3.cmds: ['ta_moler.cmd.shared.aashell', 'ta_moler.cmd.iphy.aashell'],
                             Iphy3.events: ['moler.events.shared', 'moler.events.unix',
                                            'ta_moler.events.iphy']}

            if available:
                return available[observer]

        return available
